import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.DTwTvi8b.js";const g=JSON.parse('{"title":"0001 步骤 agent 挂在发起的对话下","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/adr/0001-step-agents-under-origin-chat.md","filePath":"reference/adr/0001-step-agents-under-origin-chat.md","lastUpdated":null}'),i={name:"reference/adr/0001-step-agents-under-origin-chat.md"};function o(s,e,d,c,h,l){return t(),r("div",null,[...e[0]||(e[0]=[n('<div><h1 id="_0001-步骤-agent-挂在发起的对话下" tabindex="-1">0001 步骤 agent 挂在发起的对话下 <a class="header-anchor" href="#_0001-步骤-agent-挂在发起的对话下" aria-label="Permalink to &quot;0001 步骤 agent 挂在发起的对话下&quot;">​</a></h1><ul><li>状态：已采纳（<a href="./0018-own-worktree-option">0018</a> 增加了一种可选方式：步骤放在为需求新建的工作区中，仍挂在对话下，对话目录不变）</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>Paseo 在创建子 agent 时，如果传了 parent，会使用 parent 的工作目录而不是传入的 cwd。早期版本在两者不一致时改为创建独立 agent，结果步骤的产物写到了别处。</p><h2 id="决定" tabindex="-1">决定 <a class="header-anchor" href="#决定" aria-label="Permalink to &quot;决定&quot;">​</a></h2><p>步骤 agent 一律作为子 agent 挂在发起的对话下；仓库目录就是这个对话的工作目录。启动前核对两者，不一致时拒绝启动；创建后再核对 agent 的工作目录，不对就归档并报错。</p><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><p>使用者在对话的子 agent 列表里就能看到每一步；不会出现产物写错目录的情况。代价是必须在需求所在项目的对话中发起。</p></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/paseo-req-kit/blob/main/docs/adr/0001-step-agents-under-origin-chat.md">docs/adr/0001-step-agents-under-origin-chat.md</a> 生成。<a href="https://github.com/yiyisf/paseo-req-kit/edit/main/docs/adr/0001-step-agents-under-origin-chat.md">在 GitHub 上编辑</a></p>',2)])])}const u=a(i,[["render",o]]);export{g as __pageData,u as default};
